    const b = baseOf(s);
    s.base = b;
    const i0 = Math.max(0, bisectIdx(s, view[0]) - 1);
    const i1 = Math.min(s.pts.length - 1, d3.bisectRight(s.tn, view[1]));
    for (let i = i0; i <= i1; i++) {
