  }

  // ---- centre ----
  const lbl = player.label(t);
  if (wm) wm.text(lbl);
  if (centerOn) {
    if (hover !== null) {
      const c = cur[hover];
      const share = curTotal > 0 ? c.base / curTotal : 0;
      cTop.text(ms.truncate(nameOf(hover), ri * 1.6, 12, 700)).style("fill", d3.color(colorOf(hover)).darker(hover === OTHER ? 1.2 : 0.5));
