      const d = s.stk[k];
      rows.push({ s, p: { t: tSnap }, v: d.raw, share: d.share, py: y(d.neg ? d.y0 : d.y1),
        inside: my >= y(d.y1) - 0.5 && my <= y(d.y0) + 0.5 && d.y1 !== d.y0 });
    });
