  if (!live && kk < iStart) kk = Math.ceil(tc - winN);
  if (!live && xs(xU(kk)) < plotL - 0.5) kk = Math.min(fi, kk + 1);
  if (Math.abs(kk - tc) < 1e-9) live = true;
  const cx = live ? xs(xAtE(tc)) : xs(xU(kk));
