  vis.forEach(it => {
    let v, r, y;
    if (live) { if (!it.on || it.alpha < 0.5) return; v = it.vT; r = Math.round(it.rT); y = it.hy; }
    else { v = it.v[kk]; if (v === null) return; r = it.rk[kk]; y = ptY(it, kk); }
    rows.push({ it, v, r, y });
