  const rows = [];
  rows.push({ name: "Value", value: fmt.value(it.vT), bold: true });
  rows.push({ name: "Rank", value: "#" + Math.round(it.rT), extra: "of " + Math.round(nPres[Math.round(tc)] || vis.length) });
  const v0 = it.v[it.first];
