        .attr("fill-opacity", hidden.has(s.name) ? 0.4 : 1)
        .style("text-decoration", hidden.has(s.name) ? "line-through" : null);
      items.filter(x => x.s === s).select(".radar-legend-box")
        .attr("opacity", hidden.has(s.name) ? 0.35 : 1);
    });
