if (title) {
  svg.append("text")
    .attr("class", "radar-title")
    .attr("x", width / 2)
    .attr("y", titleSize)
    .attr("text-anchor", "middle")
    .attr("font-size",   titleSize)
    .attr("font-family", fontFamily)
    .attr("font-weight", "bold")
    .attr("fill",        axisCol)
    .text(title);
}
