// ---------------------------------------------------------------------------
// Text measurement
// ---------------------------------------------------------------------------
function measure(str, size, weight) {
  const t = svg.append("text")
    .attr("visibility", "hidden")
    .attr("font-family", fontFamily)
    .attr("font-size", size)
    .attr("font-weight", weight || "normal")
    .text(str);
