const titleOffset = title ? titleSize + 14 : 0;

// Legend (Chart.js style: centered rows of boxes + labels, wrapping)
const boxW = Math.round(legendSize * 2.4);
const boxH = Math.round(legendSize * 0.95);
const legendGap = 18;
let legendRows = [];
let legendH = 0;
