  const rr = radius * k / levels;
  if (gridShape === "circle") {
    grid.append("circle")
      .attr("class", "radar-ring")
      .attr("r", rr)
      .attr("fill", "none")
      .attr("stroke", gridCol)
      .attr("stroke-width", 1);
  } else {
    grid.append("path")
      .attr("class", "radar-ring")
      .attr("d", ringLine(axes.map(() => rr)))
      .attr("fill", "none")
      .attr("stroke", gridCol)
      .attr("stroke-width", 1);
