  .data(axes)
  .join("line")
  .attr("class", "radar-spoke")
  .attr("x1", 0).attr("y1", 0)
  .attr("x2", (d, i) => px(radius, i))
  .attr("y2", (d, i) => py(radius, i))
  .attr("stroke", gridCol)
  .attr("stroke-width", 1);

