const labels = g.append("g").attr("class", "radar-axis-labels");
labelInfo.forEach((L, i) => {
  const lx = px(radius + labelGap, i);
  const ly = py(radius + labelGap, i);
  const anchor = Math.abs(L.sin) < 0.1 ? "middle" : (L.sin > 0 ? "start" : "end");
