      .attr("x", 0)
      .attr("y", -radius * k / levels)
      .attr("dy", "0.35em")
      .attr("text-anchor", "middle")
      .attr("font-family", fontFamily)
      .attr("font-size", tickSize)
      .attr("fill", axisCol)
      .attr("fill-opacity", 0.6)
      .attr("stroke", bgcol)
