// ---------------------------------------------------------------------------
// Series
// ---------------------------------------------------------------------------
const hidden = new Set();

const seriesLayer = g.append("g").attr("class", "radar-series-layer");

const seriesG = seriesLayer.selectAll("g.radar-series")
  .data(series)
  .join("g")
  .attr("class", "radar-series")
