  .data(pointData)
  .join("circle")
  .attr("class", "radar-point")
  .attr("r", pointRadius)
  .attr("fill", p => p.s.color)
  .attr("stroke", bgcol)
  .attr("stroke-width", pointRadius > 0 ? Math.min(1.5, pointRadius * 0.4) : 0)
